        # bounding box
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)
        h = max_r - min_r + 1
        w = max_c - min_c + 1
        size = max(h, w)                     # size of the square we will create

        # build the "ring" (border of a size×size square)
        ring = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                if i == 0 or i == size - 1 or j == 0 or j == size - 1:
                    ring[i][j] = col

        # original positions of this component – they may be overwritten
        orig = set(cells)

        # helper: can we place the ring at a given top‑left (r0,c0) ?
        def can_place(r0, c0):
            if r0 < 0 or c0 < 0:
                return False
            if r0 + size > rows or c0 + size > cols:
                return False
            for i in range(size):
                for j in range(size):
                    if ring[i][j]:
                        rr, cc = r0 + i, c0 + j
                        # conflict with any cell that is non‑zero in the *original* grid
                        # and that does not belong to the current component
                        if (rr, cc) not in orig and grid[rr][cc] != 0:
